// Three-player UMS fixture: computers in different Forces start allied, remain
// hostile to the human, and an original alliance action can make them enemies.
#include "engine.h"
#include "campaign_map.h"
#include <cassert>
#include <fstream>
#include <cstdio>
#include <unistd.h>
using namespace port3ds;
int main(int argc,char**argv){assert(argc==3);std::ifstream in(argv[2],std::ios::binary);std::vector<uint8_t> map((std::istreambuf_iterator<char>(in)),{});auto chunk=[&](const char* tag,const std::vector<uint8_t>& b){for(size_t at=0;at+8<=map.size();){auto n=campaign::get(map.data()+at+4);if(!memcmp(map.data()+at,tag,4)){map.erase(map.begin()+at+8,map.begin()+at+8+n);map.insert(map.begin()+at+8,b.begin(),b.end());campaign::put(map.data()+at+4,b.size());return;}at+=8+n;}map.insert(map.end(),tag,tag+4);auto at=map.size();map.resize(at+4);campaign::put(map.data()+at,b.size());map.insert(map.end(),b.begin(),b.end());};std::vector<uint8_t> owners(12),races(12,1),forces(20);owners[0]=6;owners[1]=owners[2]=5;forces[1]=1;forces[2]=2;chunk("OWNR",owners);chunk("SIDE",races);chunk("FORC",forces);chunk("THG2",{});std::vector<uint8_t> units;auto spawn=[&](unsigned type,unsigned owner,unsigned x,unsigned y){auto at=units.size();units.resize(at+36);auto* p=units.data()+at;auto word=[&](unsigned n,unsigned v){p[n]=v;p[n+1]=v>>8;};word(4,x);word(6,y);word(8,type);p[16]=owner;p[17]=100;};spawn(106,0,384,384);spawn(0,1,384,480);spawn(106,2,1184,1024);spawn(0,1,1184,1120);chunk("UNIT",units);std::vector<uint8_t> trig(2400);campaign::put(trig.data()+8,3);trig[14]=0;trig[15]=12;auto* a=trig.data()+320;campaign::put(a+16,2);a[24]=0;a[26]=57;trig[2373]=1;chunk("TRIG",trig);auto base=std::string("/tmp/sc3ds-alliance-")+std::to_string(getpid());auto path=base+".chk";{std::ofstream out(path,std::ios::binary);out.write((char*)map.data(),map.size());}Engine e;assert(e.load(argv[1],path.c_str(),Scenario::terran_campaign_3));assert(e.start_recording((base+".journal").c_str()));e.set_fog_enabled(false);auto hp=[&](unsigned owner){UnitView u[128];auto n=e.visible_units(u,128);for(unsigned i=0;i<n;++i)if(u[i].owner==owner && u[i].type==106)return u[i].hp;return 0;};for(unsigned i=0;i<60;++i)assert(e.tick());assert(hp(0)<1500 && hp(2)==1500);SaveView view;assert(e.save_game((base+".sav").c_str(),view));Engine replay;SaveView loaded;assert(replay.load_save(argv[1],(base+".sav").c_str(),(base+".replay").c_str(),(base+".map").c_str(),loaded));for(unsigned i=0;i<300;++i){assert(e.tick() && replay.tick());assert(e.state_digest()==replay.state_digest());}assert(hp(2)>0 && hp(2)<1500);puts("UMS cross-Force computer alliance / hostile human / original explicit enemy action / active save replay PASS");}
